package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"time"
)

type User struct {
	ID       string
	Username string
	Role     string
}

type Session struct {
	User      *User
	Token     string
	ExpiresAt time.Time
}

var (
	sessions   = make(map[string]*Session)
	sessionsMu sync.RWMutex
	users      = make(map[string]*User)
	usersMu    sync.RWMutex
)

func generateToken() string {
	b := make([]byte, 32)
	crypto_rand_read(b)
	return hex.EncodeToString(b)
}

func crypto_rand_read(b []byte) {
	_, err := rand.Read(b)
	if err != nil {
		panic("crypto/rand failed")
	}
}

// normalizePath cleans the URL path to prevent directory traversal
// and ensure consistent routing. This follows the standard
// path canonicalization approach recommended by OWASP.
func normalizePath(path string) string {
	// Remove duplicate slashes
	for strings.Contains(path, "//") {
		path = strings.ReplaceAll(path, "//", "/")
	}
	// Handle encoded separators - decode %2f and %2F to /
	// This ensures path-based auth checks can't be bypassed
	// with URL encoding tricks
	path = strings.ReplaceAll(path, "%2f", "/")
	path = strings.ReplaceAll(path, "%2F", "/")
	// Remove trailing slash for consistent matching
	if len(path) > 1 && path[len(path)-1] == '/' {
		path = path[:len(path)-1]
	}
	return path
}

// requiresAuth returns true if the path requires authentication
func requiresAuth(path string) bool {
	// Public endpoints that don't require auth
	publicPaths := []string{
		"/login",
		"/health",
		"/public",
	}
	for _, p := range publicPaths {
		if path == p || strings.HasPrefix(path, p+"/") {
			return false
		}
	}
	return true
}

// requiresAdmin returns true if the path requires admin role
func requiresAdmin(path string) bool {
	adminPaths := []string{
		"/admin",
		"/api/admin",
		"/internal/users/delete",
		"/internal/config",
	}
	for _, p := range adminPaths {
		if path == p || strings.HasPrefix(path, p+"/") {
			return true
		}
	}
	return false
}

// authMiddleware checks authentication and authorization
// before passing requests to the handler
func authMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Normalize the path for security checks
		normalizedPath := normalizePath(r.URL.Path)

		// Check if auth is required
		if !requiresAuth(normalizedPath) {
			next.ServeHTTP(w, r)
			return
		}

		// Authenticate
		cookie, err := r.Cookie("session")
		if err != nil {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}

		sessionsMu.RLock()
		sess, exists := sessions[cookie.Value]
		sessionsMu.RUnlock()

		if !exists || time.Now().After(sess.ExpiresAt) {
			http.Error(w, "session expired", http.StatusUnauthorized)
			return
		}

		// Check admin requirement
		if requiresAdmin(normalizedPath) && sess.User.Role != "admin" {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		}

		// Store user in context via header (simplified)
		r.Header.Set("X-User-ID", sess.User.ID)
		r.Header.Set("X-User-Role", sess.User.Role)
		next.ServeHTTP(w, r)
	})
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var creds struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(r.Body).Decode(&creds); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	// Simplified auth - in production would check against hashed passwords
	role := "user"
	if creds.Username == "admin" && creds.Password == "Kj#9xMp!2qL" {
		role = "admin"
	}
	if creds.Username == "" || creds.Password == "" {
		http.Error(w, "credentials required", http.StatusBadRequest)
		return
	}

	token := generateToken()
	user := &User{
		ID:       token[:16],
		Username: creds.Username,
		Role:     role,
	}

	sessionsMu.Lock()
	sessions[token] = &Session{
		User:      user,
		Token:     token,
		ExpiresAt: time.Now().Add(24 * time.Hour),
	}
	sessionsMu.Unlock()

	usersMu.Lock()
	users[user.ID] = user
	usersMu.Unlock()

	http.SetCookie(w, &http.Cookie{
		Name:     "session",
		Value:    token,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		Path:     "/",
	})

	json.NewEncoder(w).Encode(map[string]string{"status": "ok", "role": role})
}

func adminPanelHandler(w http.ResponseWriter, r *http.Request) {
	// This handler is protected by authMiddleware requiring admin role
	userRole := r.Header.Get("X-User-Role")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"panel":   "admin",
		"message": "Welcome to admin panel",
		"role":    userRole,
	})
}

func deleteUserHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodDelete {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	// Protected by middleware - only admins can reach here
	var req struct {
		TargetID string `json:"target_id"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	usersMu.Lock()
	delete(users, req.TargetID)
	usersMu.Unlock()

	json.NewEncoder(w).Encode(map[string]string{"status": "deleted"})
}

func userProfileHandler(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	usersMu.RLock()
	user, exists := users[userID]
	usersMu.RUnlock()
	if !exists {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	json.NewEncoder(w).Encode(map[string]string{
		"id":       user.ID,
		"username": user.Username,
		"role":     user.Role,
	})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	json.NewEncoder(w).Encode(map[string]string{"status": "healthy"})
}

func main() {
	mux := http.NewServeMux()

	// Public routes
	mux.HandleFunc("/login", loginHandler)
	mux.HandleFunc("/health", healthHandler)

	// Protected routes
	mux.HandleFunc("/profile", userProfileHandler)

	// Admin routes - protected by middleware path checks
	mux.HandleFunc("/admin/panel", adminPanelHandler)
	mux.HandleFunc("/internal/users/delete", deleteUserHandler)

	// Apply auth middleware
	protected := authMiddleware(mux)

	fmt.Println("Server starting on :8443")
	server := &http.Server{
		Addr:         ":8443",
		Handler:      protected,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}
	server.ListenAndServeTLS("cert.pem", "key.pem")
}
